<script setup lang="ts">import {ref,computed,onMounted} from 'vue';import {networks} from '../stores/networks';import {revisions} from '../stores/revisions';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {list,detail,create} from '../api/reorders';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import NetworkDiagram from '../components/NetworkDiagram.vue';import {logValue} from '../utils/format';
const items=ref<any[]>([]),selected=ref(''),record=ref<any>(null),loadError=ref(''),source=ref(''),orderText=ref(''),networkName=ref(''),revisionName=ref(''),version=ref('r1'),description=ref(''),onlyMismatch=ref(false);const {error,busy,act}=useTask();
async function choose(id:string){selected.value=id;record.value=id?await detail(id):null}
async function refresh(){items.value=await list();if(items.value.length){if(!items.value.some(r=>r.id===selected.value))await choose(items.value[0].id)}else{selected.value='';record.value=null}}
onMounted(async()=>{try{await Promise.all([networks.load(),revisions.load()]);await refresh();if(!source.value&&revisions.items.value.length)source.value=revisions.items.value[0].id}catch(e){loadError.value=(e as Error).message}});
const sourceRevision=computed(()=>revisions.items.value.find(r=>r.id===source.value)),sourceNetwork=computed(()=>networks.items.value.find(n=>n.id===sourceRevision.value?.network_id)),nodeIds=computed(()=>(sourceNetwork.value?.nodes||[]).map((n:any)=>n.node_id));
const det=computed(()=>record.value?.detail),states=computed(()=>record.value?.states||[]),shown=computed(()=>onlyMismatch.value?states.value.filter((s:any)=>!s.match):states.value);
const fmtDiff=(v:number|null)=>v===null?'—':Number(v).toExponential(2),assignment=(a:Record<string,number>)=>Object.entries(a).map(([k,v])=>k+'='+v).join(' · ');
function fillExample(){orderText.value=[...nodeIds.value].reverse().join(', ')}
function submit(){act(async()=>{const order=orderText.value.split(/[\s,，、]+/).map(s=>s.trim()).filter(Boolean);const r=await create({revision_id:source.value,order,network_name:networkName.value,revision_name:revisionName.value,version:version.value,description:description.value});await Promise.all([networks.load(),revisions.load()]);await refresh();await choose(r.id);networkName.value='';revisionName.value=''})}
</script><template><PageHeading index="06 / 顺序重排" title="换讲解顺序，不换联合分布。" note="接收现有概率版本与完整节点顺序，生成遵循该顺序、边数最少的新网络与完整CPT；同样少时按父节点名称取首个。零概率父配置无法识别并补全0.5/0.5，极小正概率不当零；父节点上限仍为4，不可行时不留半成品。原网络、案例与报告保持原样。"/><Notice :message="loadError"/><div class="two-col"><section><div class="run-toolbar" v-if="items.length"><label>转换记录<select v-model="selected" @change="choose(selected)"><option v-for="r in items" :key="r.id" :value="r.id">{{r.detail.new_network_name}} · {{String(r.created_at).slice(0,10)}}</option></select></label></div><EmptyState v-if="!items.length" text="还没有转换记录。选择概率版本、给出完整节点顺序，即可生成最小边数的新网络与概率版本。"/><template v-if="record&&det"><h2>{{det.new_network_name}}</h2><p class="version-note">源 {{det.source_network_name}} / CPT {{det.source_version}} → {{det.new_revision_name}}（版本号 {{det.new_version}}）<br>讲解顺序 {{record.teaching_order.join(' → ')}}<br>边数 {{det.edges_before}} → {{det.edges_after}} · 对账 {{det.reconciliation.state_count}} 个联合状态 · 最大|ΔlogP| {{fmtDiff(det.reconciliation.max_abs_log_diff)}} · 零模式冲突 {{det.reconciliation.zero_pattern_mismatches}} 处 · <b>{{det.reconciliation.consistent?'逐状态一致':'存在不一致'}}</b></p><div class="reorder-compare"><figure><figcaption>原结构 · {{det.edges_before}} 条边</figcaption><NetworkDiagram :nodes="det.source_nodes"/></figure><figure><figcaption>新结构 · {{det.edges_after}} 条边</figcaption><NetworkDiagram :nodes="det.new_nodes"/></figure></div><h3>父集选择（边数最少，同样少按父节点名称取首个）</h3><div class="table-wrap"><table><thead><tr><th>节点</th><th>可用前驱</th><th>选定父节点</th></tr></thead><tbody><tr v-for="p in det.placements" :key="p.node_id"><td>{{p.node_id}}</td><td>{{p.predecessors.join(', ')||'∅'}}</td><td><b>{{p.parents.join(', ')||'∅'}}</b></td></tr></tbody></table></div><template v-if="det.unidentifiable.length"><h3>零概率父配置：无法识别，已合法补全</h3><div class="table-wrap"><table><thead><tr><th>节点</th><th>父节点</th><th>父配置</th><th>补全</th><th>原因</th></tr></thead><tbody><tr v-for="(u,i) in det.unidentifiable" :key="i"><td>{{u.node_id}}</td><td>{{u.parents.join(', ')}}</td><td>{{u.parent_values.join(', ')}}</td><td>{{u.completion.p0}} / {{u.completion.p1}}</td><td>{{u.reason}}</td></tr></tbody></table></div></template><h3>逐状态概率对账</h3><p class="method-note">零概率状态精确比对零模式；有限log概率容差 {{det.reconciliation.tolerance}}。极小正概率保持有限log值，不当作零。 <label class="inline-check"><input type="checkbox" v-model="onlyMismatch"> 只看异常状态</label></p><div class="table-wrap state-table"><table><thead><tr><th>联合状态</th><th>logP 原</th><th>logP 新</th><th>|Δ|</th><th>结论</th></tr></thead><tbody><tr v-for="(s,i) in shown" :key="i" :class="{mismatch:!s.match}"><td>{{assignment(s.assignment)}}</td><td>{{logValue(s.log_old)}}</td><td>{{logValue(s.log_new)}}</td><td>{{fmtDiff(s.abs_diff)}}</td><td>{{s.match?'一致':(s.zero_old!==s.zero_new?'零模式冲突':'超出容差')}}</td></tr></tbody></table></div><p class="hash-note">输入SHA256 {{det.input_sha256}}</p><p class="method-note">{{det.method}}</p></template></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>发起顺序转换</h2><label>源概率版本<select v-model="source" required><option v-for="r in revisions.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>新讲解顺序（全部节点，逗号/空格分隔）<textarea v-model="orderText" rows="3" required></textarea></label><p class="method-note" v-if="nodeIds.length">可用节点：{{nodeIds.join('、')}}　<button type="button" class="text-button" @click="fillExample">填入逆拓扑序示例</button></p><label>新网络名称<input v-model="networkName" required minlength="2"></label><label>新版本名称<input v-model="revisionName" required minlength="2"></label><label>版本号<input v-model="version" required></label><label>研修来源说明<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">校验顺序并转换</button></form></div></template>
